def transform(g):
    n=len(g)
    def val(i,j):
        for a,b in [(j,i),(n-1-i,j),(i,n-1-j),(n-1-j,i),(j,n-1-i),(n-1-j,n-1-i)]:
            if 0<=a<n and 0<=b<n and g[a][b]!=6: return g[a][b]
        return None
    return [[v if v!=6 else val(i,j) for j,v in enumerate(row)] for i,row in enumerate(g)]
